-- Changelog: meetstaat opent binnen de calculatie (#17).
insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-10-13','verbeterd','Calculatie','Meetstaat opent binnen de calculatie',
   'De meetstaat opent nu over de calculatie heen, met een duidelijke knop "Terug naar calculatie". Na synchroniseren staan de hoeveelheden meteen in het rekenblad, zonder te verversen. Werk je met twee schermen, kies dan via het pijltje naast de knop "In nieuw venster openen"; de calculatie herlaadt zodra je terugkomt.');
